public static int calculateEnergy(String s) {
    int energy = 0;
    int count = 1;
    int maxCount = 0;
    char lastChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == lastChar) {
            count++;
        } else {
            lastChar = c;
            count = 1;
        }
        if (count > maxCount) {
            maxCount = count;
        }
    }
    return maxCount;
}

public static List<Integer> lexicalOrder(int n) {
    LinkedList<Integer> list = new LinkedList<Integer>();
    for (int i = 1; i <= n; i++) {
        list.add(i);
        int j = 0;
        while (j < list.size() && i != list.get(j)) {
            j++;
        }
        if (i == list.get(j)) {
            list.removeLast();
        }
    }
    return list;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueElements = new HashSet<>();
    int sum = 0;
    for (int num : nums) {
        if (uniqueElements.add(num)) {
            sum += num;
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        count++;
        n -= root * root;
    }
    return count;
}

